class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        def count(n: int) -> int:
            if n == 0:
                return 0

            digits = list(map(int, str(n)))
            num_digits = len(digits)

            from functools import lru_cache

            @lru_cache(None)
            def dfs(idx: int, current_sum: int, current_product: int, is_started: bool, is_tight: bool) -> int:
                if idx == num_digits:
                    if not is_started:
                        return 0

                    if current_product == 0:
                        return 1
                    else:
                        return 1 if current_product % current_sum == 0 else 0

                limit = digits[idx] if is_tight else 9
                total_count = 0

                for digit in range(10):
                    new_tight = is_tight and (digit == limit)

                    if not is_started:
                        if digit == 0:
                            total_count += dfs(idx + 1, 0, 1, False, new_tight)
                        else:
                            total_count += dfs(idx + 1, digit, digit, True, new_tight)
                    else:
                        new_sum = current_sum + digit
                        if digit == 0:
                            new_prod = 0
                        else:
                            new_prod = current_product * digit
                        total_count += dfs(idx + 1, new_sum, new_prod, True, new_tight)

                return total_count

            return dfs(0, 0, 1, False, True)

        return count(r) - count(l - 1)

from typing import List, Dict
from collections import deque

class TrieNode:
    def __init__(self):
        self.children: Dict[str, 'TrieNode'] = {}
        self.count = 0

class Solution:
    def longestCommonPrefix(self, words: List[str], k: int) -> List[int]:
        n = len(words)
        if n < k:
            return [0] * n

        root = TrieNode()
        # Build Trie and count frequencies
        for word in words:
            node = root
            for char in word:
                if char not in node.children:
                    node.children[char] = TrieNode()
                node = node.children[char]
                node.count += 1

        # Identify global_base: max depth among nodes with count >= k + 1
        global_base = 0

        # Map: depth -> count of nodes at that depth with count == k
        depth_nodes_count: Dict[int, int] = {}

        # BFS to collect stats
        queue = deque([(root, 0)])
        while queue:
            node, depth = queue.popleft()
            if node.count >= k + 1:
                if depth > global_base:
                    global_base = depth
            if node.count == k:
                if depth not in depth_nodes_count:
                    depth_nodes_count[depth] = 0
                depth_nodes_count[depth] += 1
            # Add children to queue
            for child in node.children.values():
                queue.append((child, depth + 1))

        # Determine M1 and M2 from singleton depths
        # Singletons are depths where depth_nodes_count[d] == 1
        singleton_depths = [d for d, cnt in depth_nodes_count.items() if cnt == 1]
        singleton_depths.sort(reverse=True)

        ans = [global_base] * n

        # For each word, check if it passes through the specific node at depth m1
        # that has count == k. If so, m1 is blocked for this word.
        # We then check if m2 is blocked, and so on, but optimized by checking counts on the path.
        for i, word in enumerate(words):
            if singleton_depths:
                node = root
                blocked_depths = set()

                # Traverse the path of the word
                # We only need to check depths up to m1 because singleton_depths are sorted descending
                # and we want the max valid depth. Any depth > m1 is not a singleton.
                limit = min(len(word), singleton_depths[0])

                for j in range(limit):
                    char = word[j]
                    if char not in node.children:
                        break
                    node = node.children[char]
                    depth = j + 1

                    # Check if this depth is a singleton and the current node is the one with count k
                    if depth in depth_nodes_count and depth_nodes_count[depth] == 1:
                        if node.count == k:
                            blocked_depths.add(depth)

                # Find the largest singleton depth that is NOT blocked
                best_singleton = 0
                for d in singleton_depths:
                    if d not in blocked_depths:
                        best_singleton = d
                        break

                if best_singleton > ans[i]:
                    ans[i] = best_singleton

        return ans

class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n = len(str1)
        m = len(str2)
        length = n + m - 1

        # Initialize word with placeholders
        word = [''] * length
        forced = [None] * length

        # Step 1: Apply 'T' constraints
        for i, char in enumerate(str1):
            if char == 'T':
                for j in range(m):
                    idx = i + j
                    if forced[idx] is not None and forced[idx] != str2[j]:
                        return ""
                    forced[idx] = str2[j]

        # Step 2: Identify critical 'F' windows
        # A window is critical if str1[i] == 'F' and the forced characters 
        # do not already make the substring different from str2.
        critical_windows = []

        for i in range(n):
            if str1[i] == 'F':
                # Check if the window is already satisfied by forced characters
                satisfied = False
                for j in range(m):
                    idx = i + j
                    if forced[idx] is not None and forced[idx] != str2[j]:
                        satisfied = True
                        break

                if not satisfied:
                    # This window is critical. It matches str2 on all forced positions.
                    # We need to find free positions in [i, i+m-1].
                    free_positions = []
                    for j in range(m):
                        idx = i + j
                        if forced[idx] is None:
                            free_positions.append(idx)

                    if not free_positions:
                        # No free positions to break the equality -> Impossible
                        return ""

                    critical_windows.append({
                        'start': i,
                        'last_free': free_positions[-1]
                    })

        # Step 3: Precompute 'must_break_at' for each index k.
        # must_break_at[k] contains characters that CANNOT be placed at k
        # because if we place them, we fail to break a critical window where k is the last free position.
        must_break_at = [set() for _ in range(length)]

        for cw in critical_windows:
            last_free = cw['last_free']
            start = cw['start']
            # At index last_free, we MUST pick a char != str2[last_free - start]
            forbidden_char = str2[last_free - start]
            must_break_at[last_free].add(forbidden_char)

        # Step 4: Greedy construction
        for k in range(length):
            if forced[k] is not None:
                word[k] = forced[k]
            else:
                forbidden = must_break_at[k]
                c = 'a'
                while c in forbidden:
                    c = chr(ord(c) + 1)
                word[k] = c

        return "".join(word)

