    solve()

from typing import List

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        if not grid or not grid[0]:
            return 0

        n, m = len(grid), len(grid[0])
        # Directions mapping to ensure clockwise turn logic (d -> (d+1)%4) works:
        # 0: (1, 1)  -> SE
        # 1: (1, -1) -> SW
        # 2: (-1, -1) -> NW
        # 3: (-1, 1) -> NE
        # Clockwise sequence: SE -> SW -> NW -> NE -> SE
        dirs = [(1, 1), (1, -1), (-1, -1), (-1, 1)]

        # Memoization table: (r, c, d, turn_made, parity) -> max_length_from_here
        # parity: 1 means next value should be 2 (odd step), 0 means next value should be 0 (even step)
        # Sequence after '1': 2, 0, 2, 0...
        # Step 1 (first neighbor): expect 2 (parity=1)
        # Step 2: expect 0 (parity=0)
        memo = {}

        def get_next_val(parity: int) -> int:
            return 2 if parity == 1 else 0

        def dfs(r: int, c: int, d: int, turn_made: bool, parity: int) -> int:
            state = (r, c, d, turn_made, parity)
            if state in memo:
                return memo[state]

            if r < 0 or r >= n or c < 0 or c >= m:
                return 0

            val = grid[r][c]
            expected = get_next_val(parity)

            if val != expected:
                return 0

            res = 1

            # Option 1: Continue in same direction
            nr, nc = r + dirs[d][0], c + dirs[d][1]
            if 0 <= nr < n and 0 <= nc < m:
                res = max(res, 1 + dfs(nr, nc, d, turn_made, 1 - parity))

            # Option 2: Turn clockwise (only if not already turned)
            if not turn_made:
                nd = (d + 1) % 4
                nr, nc = r + dirs[nd][0], c + dirs[nd][1]
                if 0 <= nr < n and 0 <= nc < m:
                    res = max(res, 1 + dfs(nr, nc, nd, True, 1 - parity))

            memo[state] = res
            return res

        max_len = 0
        has_one = False

        for i in range(n):
            for j in range(m):
                if grid[i][j] == 1:
                    has_one = True
                    # If the grid is just [[1]], max_len should be 1.
                    # The loop below only updates if there is a valid neighbor.
                    if n == 1 and m == 1:
                        max_len = max(max_len, 1)
                    else:
                        for d in range(4):
                            nr, nc = i + dirs[d][0], j + dirs[d][1]
                            if 0 <= nr < n and 0 <= nc < m:
                                # Start DFS from neighbor. 
                                # This neighbor is step 1, so parity = 1 (expect 2).
                                path_len = dfs(nr, nc, d, False, 1)
                                max_len = max(max_len, path_len + 1)

        return max_len if has_one else 0

from typing import List

class Solution:
    def minimumIncrements(self, nums: List[int], target: List[int]) -> int:
        total_ops = 0
        for t in target:
            min_ops = float('inf')
            for n in nums:
                rem = n % t
                if rem == 0:
                    cost = 0
                else:
                    cost = t - rem
                if cost < min_ops:
                    min_ops = cost
            total_ops += min_ops
        return total_ops

class Solution:
    def minCostGoodCaption(self, caption: str) -> str:
        n = len(caption)
        if n < 3:
            return ""

        # dp[i][c] = minimum cost to complete the string from index i,
        # given that the FIRST group of the suffix starts at i with character c.
        # c is 0-25 representing 'a'-'z'.
        INF = float('inf')
        dp = [[INF] * 26 for _ in range(n + 1)]

        # Base case: at index n, the cost to complete is 0.
        for c in range(26):
            dp[n][c] = 0

        # Precompute best and second best characters for each index to optimize transitions
        best_c_min = [-1] * (n + 1)
        best_c_sec = [-1] * (n + 1)

        # Fill best/second best arrays backwards
        for k in range(n, -1, -1):
            candidates = []
            for c in range(26):
                if dp[k][c] != INF:
                    candidates.append((dp[k][c], c))

            if not candidates:
                continue

            # Sort by cost, then by character
            candidates.sort(key=lambda x: (x[0], x[1]))

            if len(candidates) >= 1:
                best_c_min[k] = candidates[0][1]
            if len(candidates) >= 2:
                best_c_sec[k] = candidates[1][1]

        # Fill DP table backwards
        for i in range(n - 1, -1, -1):
            next_states_info = {}
            for L in [3, 4, 5]:
                if i + L <= n:
                    idx = i + L
                    if idx not in next_states_info:
                        next_states_info[idx] = (best_c_min[idx], best_c_sec[idx])

            for c in range(26):
                min_val = INF

                for L in [3, 4, 5]:
                    if i + L > n:
                        continue

                    idx = i + L

                    # Calculate cost of current segment [i, i+L) converted to char c
                    seg_cost = 0
                    for k in range(L):
                        char_code = ord(caption[i+k]) - ord('a')
                        seg_cost += abs(char_code - c)

                    # Find min cost from next state with char != c
                    b1_char, b2_char = next_states_info[idx]

                    if b1_char != c:
                        cost_next = dp[idx][b1_char]
                    else:
                        cost_next = dp[idx][b2_char]

                    if cost_next == INF:
                        continue

                    total = seg_cost + cost_next
                    if total < min_val:
                        min_val = total

                dp[i][c] = min_val

        # Find global minimum cost at dp[0][c]
        global_min = INF
        for c in range(26):
            if dp[0][c] < global_min:
                global_min = dp[0][c]

        if global_min == INF:
            return ""

        # Reconstruct the lexicographically smallest string
        res = []
        curr = 0

        while curr < n:
            # 1. Find the smallest character 'c' that can start a group at 'curr'
            best_c = -1
            for c in range(26):
                if dp[curr][c] == global_min:
                    best_c = c
                    break

            if best_c == -1:
                break # Should not happen

            candidates = []
            for L in [3, 4, 5]:
                if curr + L > n:
                    continue

                # Calculate cost of this specific segment
                seg_cost = 0
                for k in range(L):
                    char_code = ord(caption[curr+k]) - ord('a')
                    seg_cost += abs(char_code - best_c)

                idx = curr + L

                # Determine cost of rest
                b1_char, b2_char = best_c_min[idx], best_c_sec[idx]

                if b1_char != best_c:
                    cost_next = dp[idx][b1_char]
                else:
                    cost_next = dp[idx][b2_char]

                if cost_next == INF:
                    continue

                if seg_cost + cost_next != global_min:
                    continue

                # Determine starting char of next group
                if idx == n:
                    next_c = 26 
                else:
                    if b1_char != best_c:
                        next_c = b1_char
                    else:
                        next_c = b2_char

                candidates.append((L, next_c))

            # Select best L
            best_L = -1
            for L, next_c in candidates:
                if next_c < best_c:
                    if best_L == -1 or L < best_L:
                        best_L = L
                elif next_c > best_c:
                    if best_L == -1 or L > best_L:
                        best_L = L

            res.append(best_c * best_L)
            curr += best_L

        return "".join(res)

import sys

# Increase recursion depth just in case, though iterative approach is used
sys.setrecursionlimit(2000)

def solve():
    # Read all input from stdin
    input_data = sys.stdin.read().split()

    if not input_data:
        return

    iterator = iter(input_data)

    try:
        N = int(next(iterator))
        p = int(next(iterator))
    except StopIteration:
        return

    # Read matrix A
    A = []
    for _ in range(N):
        row = []
        for _ in range(N):
            row.append(int(next(iterator)))
        A.append(row)

    # Prepare matrix M based on p
    # Logic derived from properties of power sums in finite fields:
    # 1. If p = 2: The only non-zero value is 1. Replacing 0s with 1s in A gives matrix X.
    #    Since there is only 1 choice for each zero, the sum is simply X^2 mod 2.
    # 2. If p > 2: For any path in the expansion of B^p, if an edge corresponding to a zero 
    #    in A is used k times, its contribution involves sum_{x=1}^{p-1} x^k.
    #    This sum is 0 mod p unless p-1 divides k. Since path length is p (prime) and p > 2,
    #    p-1 does not divide p. The only surviving terms correspond to paths with NO zero edges.
    #    Thus, we treat zeros as 0 in the matrix M and compute M^p mod p.

    M = [[0] * N for _ in range(N)]

    if p == 2:
        for i in range(N):
            for j in range(N):
                if A[i][j] != 0:
                    M[i][j] = A[i][j] % 2
                else:
                    M[i][j] = 1 % 2
    else:
        for i in range(N):
            for j in range(N):
                if A[i][j] != 0:
                    M[i][j] = A[i][j] % p
                else:
                    M[i][j] = 0

    # Matrix multiplication function modulo p
    def mat_mul(X, Y, mod):
        size = len(X)
        Z = [[0] * size for _ in range(size)]
        for i in range(size):
            for k in range(size):
                if X[i][k] == 0:
                    continue
                val_x = X[i][k]
                for j in range(size):
                    Z[i][j] = (Z[i][j] + val_x * Y[k][j]) % mod
        return Z

    # Matrix exponentiation function
    def mat_pow(X, power, mod):
        size = len(X)
        # Identity matrix
        res = [[0] * size for _ in range(size)]
        for i in range(size):
            res[i][i] = 1

        base = X
        while power > 0:
            if power % 2 == 1:
                res = mat_mul(res, base, mod)
            base = mat_mul(base, base, mod)
            power //= 2
        return res

    # Compute M^p
    result_matrix = mat_pow(M, p, p)

    # Output the result
    for i in range(N):
        row_str = " ".join(str(x) for x in result_matrix[i])
        print(row_str)

if __name__ == '__main__':
    solve()

from collections import Counter

class Solution:
    def makeStringGood(self, s: str) -> int:
        # Count frequency of each character
        freq_map = Counter(s)
        # Get unique frequencies present in the string
        unique_freqs = sorted(list(freq_map.values()))

        # Helper function to calculate cost for a target frequency T
        def calculate_cost(target: int) -> int:
            if target == 0:
                # If target is 0, we delete all characters
                return len(s)

            surplus = 0
            deficit = 0

            for f in unique_freqs:
                if f > target:
                    surplus += (f - target)
                elif f < target:
                    deficit += (target - f)

            # Cost is sum of absolute differences minus the amount we can "transfer"
            # Transfer cost is 1 per unit (Change operation)
            # Delete/Insert cost is 2 per unit (1 delete + 1 insert)
            # So we save 1 per unit transferred.
            # Total cost = (surplus + deficit) - min(surplus, deficit)
            return (surplus + deficit) - min(surplus, deficit)

        # Consider each unique frequency as a potential target
        min_ops = float('inf')
        for f in unique_freqs:
            cost = calculate_cost(f)
            if cost < min_ops:
                min_ops = cost

        # Also consider target frequency 0 (delete everything)
        cost_zero = calculate_cost(0)
        if cost_zero < min_ops:
            min_ops = cost_zero

        return min_ops
